import WebSocket from 'ws';

const base = process.env.EDGE_BASE ?? 'ws://127.0.0.1:8787';
const token = process.env.EDGE_TOKEN ?? 'dev-token';

// 256-bin range-coded frame generated by serverrs/src/codec/range.rs.
const FIXTURE =
  '107eff0000000100000020405c226a239d31ea95e25068027d8b60f2ad3a14a8eb99e5be1e6861c4b09e0b833e6ac3b49888c1a019f1da626a18d71c2a6587f216633a641a5a15f79e7babe80486bdf13383e6c7c8f8d5caa8b94d1458eb39218648e5ee089ad24555073e';
const frame = Buffer.from(FIXTURE, 'hex');

const ingest = new WebSocket(`${base}/ingest/test/d1`, { headers: { Authorization: `Bearer ${token}` } });
const events = [];
ingest.on('open', () => {
  console.log('ingest open');
  ingest.send(JSON.stringify({cmd:'hello', instance:'test', dongle:'d1', codec:'range', maxViewers:50, history:{mode:'do-ring', bins:256, frames:32}}));
  setTimeout(() => ingest.send(frame), 200);
});
ingest.on('message', (d) => { console.log('ingest msg', d.toString().slice(0, 200)); });
ingest.on('error', (e) => console.error('ingest err', e.message));

setTimeout(() => {
  const viewer = new WebSocket(`${base}/v1/test/d1/fft?history=1`);
  viewer.binaryType = 'arraybuffer';
  viewer.on('open', () => { console.log('viewer open'); setTimeout(() => ingest.send(frame), 100); });
  viewer.on('message', (data) => {
    const b = Buffer.from(data);
    console.log('viewer msg type', b[0], 'len', b.length, b[0] === 0x0d ? `frames=${b.readUInt16LE(1)} bins=${b.readUInt32LE(3)}` : '');
    events.push(b[0]);
    if (events.includes(0x0d) && events.includes(0x10)) {
      fetch(`${base.replace(/^ws/, 'http')}/stats/test/d1`, { headers: { Authorization: `Bearer ${token}` } })
        .then(r => r.json()).then(s => { console.log('stats', JSON.stringify(s)); process.exit(0); })
        .catch(e => { console.error(e); process.exit(1); });
    }
  });
  viewer.on('error', (e) => console.error('viewer err', e.message));
}, 500);

setTimeout(() => { console.error('timeout; events=', events); process.exit(2); }, 4000);
